npm audit --json 2>/dev/null | node -e '
const fs=require("fs"); const d=JSON.parse(fs.readFileSync(0,"utf8"));
const vulns=d.vulnerabilities||{};
const rows=Object.entries(vulns).map(([name,v])=>({
  name, severity:v.severity, range:v.range, via:(v.via||[]).map(x=>typeof x==="string"?x:(x.title||x.name||x.source)).slice(0,3),
  fixAvailable:v.fixAvailable, effects:v.effects||[], isDirect:v.isDirect
}));
rows.sort((a,b)=> ({critical:0,high:1,moderate:2,low:3}[a.severity]-{critical:0,high:1,moderate:2,low:3}[b.severity]||a.name.localeCompare(b.name));
console.log(JSON.stringify({auditMeta:d.metadata, count:rows.length, rows}, null, 2));
' ; echo '--- human ---' ; npm audit 2>&1 | tail -n 80

pwd; ls package-lock.json package.json; npm audit 2>&1; echo '===='; npm audit --omit=dev 2>&1; echo '==== JSON summary ===='; npm audit --json 2>/dev/null | node --input-type=module -e '
const chunks=[]; for await (const c of process.stdin) chunks.push(c);
const d=JSON.parse(Buffer.concat(chunks).toString());
const vulns=d.vulnerabilities||{};
const rows=Object.entries(vulns).map(([name,v])=>({
  name,
  severity:v.severity,
  range:v.range,
  isDirect:v.isDirect,
  fixAvailable:v.fixAvailable===true ? true : v.fixAvailable && typeof v.fixAvailable==="object" ? v.fixAvailable : v.fixAvailable,
  via:(v.via||[]).slice(0,4).map(x=> typeof x==="string" ? x : {title:x.title,severity:x.severity,cwe:x.cwe,url:x.url,range:x.range})
}));
const order={critical:0,high:1,moderate:2,low:3,info:4};
rows.sort((a,b)=> (order[a.severity]-order[b.severity]) || a.name.localeCompare(b.name));
console.log(JSON.stringify({metadata:d.metadata, rows}, null, 2));
'

